const text = ($json.message && $json.message.text) || '';
const chatId = $json.message && $json.message.chat && $json.message.chat.id;

const match = text.match(/^\/render\s+(\S+)/);
if (!match) {
  return []; // не команда /render — молча выходим, ничего не делаем
}

const projectId = match[1].trim();
const parts = projectId.split('_');
const channelKey = parts.slice(2).join('_');

return [{ json: { projectId, channelKey, chatId } }];

const proj = $('Читаем проект').first().json;
const meta = $('Нормализуем вход').first().json;
// Модель иногда пишет метку без квадратных скобок или с другим регистром
// ('Timecodes' вместо '[Timecodes]') — ищем её гибко, а не только точную
// строку, чтобы замена не срабатывала молча вхолостую.
const timecodedDescription = $('Собираем текст таймкодов').first().json.timecodesText
  ? proj.ai_Description.replace(/\[?Timecodes\]?/i, $('Собираем текст таймкодов').first().json.timecodesText)
  : proj.ai_Description;

// Хэштеги генерируются GPT в отдельную колонку, но раньше никогда не попадали
// в финальное описание — дописываем их в конец, если они есть.
const fullDescription = proj.ai_Hashtags
  ? `${timecodedDescription}\n\n${proj.ai_Hashtags}`
  : timecodedDescription;

// Колонки шаблона канала помечены значком-эмодзи в начале имени —
// ищем по имени без учёта ведущего значка, чтобы колонку можно было
// переименовать/переставить в таблице, не трогая этот код.
// Иногда модель вместо реального текста оверлея (1-2 коротких слова)
// оставляет объясняющую фразу-заглушку вроде "(none for guides)" —
// такой текст не должен попасть на кадр буквально. Отсекаем это
// автоматически здесь, один раз и навсегда: не короткая фраза (больше
// 4 слов) или есть скобки — считаем это мусором и подставляем пустую
// строку, как для обычного гайда без оверлея. Ручная чистка ячейки в
// таблице для этого больше не нужна — рендер сам никогда не покажет
// такой текст, что бы ни лежало в ai_OverlayText.
function sanitizeOverlayText(raw) {
  const text = (raw || '').trim();
  if (!text) return '';
  const looksLikeExplanation = /[()]/.test(text) || text.split(/\s+/).length > 4;
  return looksLikeExplanation ? '' : text;
}

function findByLabel(row, label) {
  const key = Object.keys(row).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// НОВОЕ (19.09, ночь): раньше каждый параметр сборщика видео нужно было
// дописывать сюда вручную (findByLabel + запись в payload) — то есть
// добавление новой ручки в таблице требовало правки кода здесь. Теперь,
// как у Художника (🎨) и Писателя (🖋), сборщик видео читает ВСЕ колонки
// с иконкой 🎬 автоматически: имя колонки "🎬tmpl_BassGainDb" превращается
// в поле payload "bassGainDb" без единой строчки кода на каждый параметр.
// Чтобы добавить новую ручку — просто добавить колонку "🎬tmpl_ИмяРучки"
// в таблицу; чтобы убрать — удалить колонку. Здесь ничего не ломается.
//
// tmpl_OverlayStyle исключён из автосбора: это не одно значение, а строка
// "font:...; size:...", её нужно сначала разобрать на части (см. ниже).
function collectByIcon(row, icon, excludeLabels) {
  const result = {};
  for (const key of Object.keys(row)) {
    if (!key.includes(icon)) continue;
    const label = key.replace(/^[^a-zA-Z]+/, '');
    if (!label.startsWith('tmpl_')) continue;
    if (excludeLabels.includes(label)) continue;
    const value = row[key];
    if (value === undefined || value === null || value === '') continue;
    const paramName = label.slice('tmpl_'.length);
    const camelName = paramName.charAt(0).toLowerCase() + paramName.slice(1);
    result[camelName] = value;
  }
  return result;
}

// Разбираем 'font:Courier Prime; size:44; color:#FFFFFF' из шаблона канала
// в отдельные поля — если шаблона нет или парсинг не удался, оставляем
// пустыми, чтобы сборщик видео сам применил разумные значения по умолчанию.
function parseOverlayStyle(raw) {
  const result = {};
  if (!raw) return result;
  for (const part of raw.split(';')) {
    const [key, value] = part.split(':').map(s => s && s.trim());
    if (key === 'font') result.overlayFont = value;
    if (key === 'size') result.overlaySize = value;
    if (key === 'color') result.overlayColor = value;
    if (key === 'shadow') result.overlayShadow = value;
    if (key === 'margin') result.overlayMargin = value;
  }
  return result;
}
const styleRow = $('Читаем стиль оверлея').first().json;
const overlayStyle = parseOverlayStyle(findByLabel(styleRow, 'tmpl_OverlayStyle'));

const autoParams = collectByIcon(styleRow, '🎬', ['tmpl_OverlayStyle']);
// Приоритет — решение редактора конкретно для этой сцены (ai_TargetBrightness,
// проставляется при согласовании картинки) перебивает общий дефолт канала,
// который уже пришёл из tmpl_TargetBrightness через общий автосбор выше.

const loopCount = proj.sys_LoopCount;

const payload = {
  projectId: proj.sys_ProjectID,
  imageUrl: proj.ai_ApprovedImageUrl || proj.ai_ImageUrl,
  audioZipUrl: proj.sys_AudioZipUrl,
  overlayText: sanitizeOverlayText(proj.ai_OverlayText),
  overlayPosition: proj.ai_OverlayPosition || 'center',
  ...overlayStyle,
  ...autoParams,
  ...(proj.ai_TargetBrightness ? { targetBrightness: proj.ai_TargetBrightness } : {}),
  ...(loopCount ? { loopCount } : {})
};

for (const key of Object.keys(proj)) {
  if (key.startsWith('fx_') && proj[key]) {
    payload[key] = proj[key];
  }
}

return [{ json: {
  chatId: meta.chatId,
  projectId: proj.sys_ProjectID,
  title: proj.ai_Title,
  description: fullDescription,
  tags: proj.ai_Tags || '',
  pinnedComment: proj.ai_PinnedComment || '',
  payload
} }];

const msg = $json.message;
if (!msg || !msg.reply_to_message) return [];

const text = msg.text || '';
const urlMatch = text.match(/https?:\/\/\S+/);
if (!urlMatch) return []; // не ссылка на треки — не наш случай

const repliedText = (msg.reply_to_message.text || msg.reply_to_message.caption || '');
const idMatch = repliedText.match(/(\d{8})_?(\d{6})_?([A-Za-z0-9]+)/);
if (!idMatch) return [];

const projectId = idMatch[1] + '_' + idMatch[2] + '_' + idMatch[3];
const channelKey = idMatch[3];
const chatId = msg.chat.id;
let audioZipUrl = urlMatch[0];
// Превращаем обычную ссылку Google Drive в прямую ссылку на скачивание,
// какой бы формат ни вставила Татьяна — руками ничего преобразовывать не нужно
const driveMatch = audioZipUrl.match(/\/d\/([a-zA-Z0-9_-]+)/) || audioZipUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
if (driveMatch) {
  audioZipUrl = `https://drive.google.com/uc?export=download&id=${driveMatch[1]}`;
}

return [{ json: { projectId, channelKey, chatId, audioZipUrl } }];

function getEntry() {
  try { return $('Парсим ссылку на треки').first().json; } catch (e) {}
  try { return $('Парсим команду /render').first().json; } catch (e) {}
  throw new Error('Не найден источник входа ни по одной ветке');
}
function getSheetName() {
  try { return $('Находим лист канала (треки)').first().json.SheetName; } catch (e) {}
  try { return $('Находим лист канала (render)').first().json.SheetName; } catch (e) {}
  throw new Error('Не найдено имя листа ни по одной ветке');
}
const entry = getEntry();
const sheetName = getSheetName();
return [{ json: { projectId: entry.projectId, channelKey: entry.channelKey, chatId: entry.chatId, sheetName } }];

const proj = $('Читаем проект').first().json;
const info = $('Считаем длительности треков').first().json;
const channelRow = $json;

function findByLabel(row, label) {
  const key = Object.keys(row).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// НОВОЕ (24.09): названия тайм-кодов Редактор пишет заранее — пункт 4
// текстового блока, согласованный автором, лежит в колонке
// ai_TimecodeNames (по одному названию на строку). Имена файлов больше не
// используются: переименовываются ВСЕ треки. Берём заготовленные по
// порядку — первый трек получает первое название и т.д. Лишние названия
// просто не используются. Если заготовленных меньше, чем треков (или их
// нет вообще — старый проект), недостающие придумывает GPT по правилам
// канала из таблицы.
const prewritten = String(proj.ai_TimecodeNames || '')
  .split('\n').map(s => s.trim()).filter(Boolean);

const needsNaming = info.tracks.filter((t, pos) => !prewritten[pos]);

if (needsNaming.length === 0) {
  return [{ json: { skipGpt: true, prewritten, tracks: info.tracks, totalDurationSeconds: info.totalDurationSeconds } }];
}

// Как называть — правила канала из таблицы (PackagingRules, раздел про
// тайм-коды) и паспорт персонажа; в коде только формат ответа.
const packagingRules = findByLabel(channelRow, 'tmpl_PackagingRules') || '';
const characterPassport = findByLabel(channelRow, 'tmpl_CharacterPassport') || '';

const systemPrompt = 'Придумай названия для инструментальных треков YouTube-видео по правилам канала ниже.\n\n' +
  (characterPassport ? 'Персонаж канала: ' + characterPassport + '\n\n' : '') +
  (packagingRules ? 'Правила канала:\n' + packagingRules + '\n\n' : '') +
  'Верни JSON строго такого вида: {"names": {"<index>": "Name", ...}} — по одному имени на каждый индекс из списка.';

const userPrompt = 'Описание выпуска: ' + (proj.ai_DescriptionEN || proj.ai_Description || proj.ai_UserBrief || '') + '\n\n' +
  (prewritten.length ? 'Уже есть названия (не повторяй их): ' + prewritten.join('; ') + '\n\n' : '') +
  'Придумай названия для треков с такими индексами: ' + needsNaming.map(t => t.index).join(', ');

return [{ json: { skipGpt: false, prewritten, systemPrompt, userPrompt, tracks: info.tracks, totalDurationSeconds: info.totalDurationSeconds } }];

function getBase() {
  try { return $('Готовим запрос на названия треков').first().json; } catch (e) {}
  throw new Error('base not found');
}
const base = getBase();
let names = {};

if (!base.skipGpt) {
  try {
    const raw = $('OpenAI: названия треков').first().json.choices[0].message.content;
    const parsed = JSON.parse(raw);
    names = parsed.names || {};
  } catch (e) {
    names = {};
  }
}

// НОВОЕ (01.10): после часа YouTube понимает только «1:00:22», а не «60:22».
function formatTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const ss = String(s).padStart(2, '0');
  return h > 0 ? h + ':' + String(m).padStart(2, '0') + ':' + ss : m + ':' + ss;
}

// НОВОЕ (24.09): переименовываются ВСЕ треки, имена файлов не
// используются. Сначала — названия, заготовленные Редактором и
// согласованные автором (ai_TimecodeNames), по порядку; для треков, на
// которые их не хватило, — придуманные GPT; имя файла — только крайний
// запасной вариант, если не сработало ни то, ни другое.
const prewritten = base.prewritten || [];
const lines = base.tracks.map((t, pos) => {
  const title = prewritten[pos] || names[String(t.index)] || t.filename;
  return formatTime(t.startSeconds) + ' ' + title;
});

// Ручное значение в таблице побеждает, если оно есть. Если пусто —
// повторяем ровно то же правило, что уже применяет питон-сборщик сам
// (build_audio_track): меньше часа — луп x2, час и больше — без лупа.
// Иначе тут была рассинхронизация: сборщик мог зациклить видео, а этот
// узел ничего об этом не знал и не ставил метку Repeat в таймкоды.
const manualLoopCount = parseInt($('Читаем проект').first().json.sys_LoopCount);
const loopCount = manualLoopCount || (base.totalDurationSeconds < 3600 ? 2 : 1);
if (loopCount > 1) {
  // НОВОЕ (25.09): totalDurationSeconds — это КОНЕЦ последнего трека, а
  // второй проход начинается после паузы-стыка (tmpl_GapSeconds). К тому же
  // секунды округлялись вниз — клик по «Repeat» попадал в хвост последнего
  // трека. Теперь: конец + пауза, с округлением ВНИЗ (27.09) — вверх уводило
  // клик внутрь второго прохода, в середину фейда; вниз — в паузу перед ним.
  const styleRow = $('Читаем стиль оверлея').first().json;
  const gapKey = Object.keys(styleRow).find(k => k.replace(/^[^a-zA-Z]+/, '') === 'tmpl_GapSeconds');
  const gap = parseFloat(gapKey ? styleRow[gapKey] : 0) || 0;
  lines.push(formatTime(Math.floor(base.totalDurationSeconds + gap)) + ' Repeat');
}

return [{ json: { timecodesText: lines.join('\n') } }];

const incoming = $json.retryCount;
const retryCount = (incoming === undefined || incoming === null) ? 0 : incoming;
return [{ json: { retryCount } }];

const privacyStatus = ($json.items && $json.items[0] && $json.items[0].status && $json.items[0].status.privacyStatus) || 'unknown';
const retryCount = $('Готовим попытку').first().json.retryCount;
return [{ json: { privacyStatus, retryCount } }];

const incoming = $json.retryCount;
const retryCount = (incoming === undefined || incoming === null) ? 0 : incoming;
return [{ json: { retryCount } }];

const retryCount = $('Готовим попытку субтитров').first().json.retryCount;
const items = $json.items || [];
const asrTrack = items.find(i => i.snippet && i.snippet.trackKind === 'ASR');
return [{ json: { retryCount, captionId: asrTrack ? asrTrack.id : null } }];
